"""创作者标识（品牌横幅）内嵌资源。

以 base64 内联，避免 onefile 打包后找不到外部 PNG。
来源：用户提供的「柳江巷」创作者标识横幅（头像 + 创作者徽章 + 柳江酱紫 + 版本行）。
"""

from __future__ import annotations

CREATOR_BANNER_PNG = (
""
)

#: 横幅原始像素尺寸（用于按比例缩放，保持不拉伸）
BANNER_WIDTH = 403
BANNER_HEIGHT = 96

#: 圆形头像在原横幅里的位置与边长。
#: 用 4 倍放大加坐标网格实测出来的：圆心约 (57, 50)、直径约 60。
#: 框比直径大一点，留 0.5px 给抗锯齿，但不能大太多——多出来的会变成
#: 一圈深紫描边，缩到 44px 显示时那圈显得很厚。
AVATAR_RECT = (27, 20, 60, 60)


def avatar_pixmap(pixel_size: int):
    """裁出横幅里的圆形头像，输出 ``pixel_size`` × ``pixel_size`` 像素的位图。

    为什么不直接把整张横幅缩放贴上去：横幅只有 403×96，侧栏能给的宽度是
    180，缩放比 2.24:1。图里 22px 高的「柳江巷」会剩 10px，9px 高的版本行
    只剩 4px——这个尺寸下任何插值结果都是糊的，换 SmoothTransformation 也没用。
    头像本身是照片，缩到 44px 仍然清晰，所以只把头像留成位图。

    这里**不设 devicePixelRatio**：实测 ``QLabel.setPixmap`` 会把传入 pixmap
    的 DPR 抹回 1.0（物理尺寸同时被压回逻辑尺寸），高 DPI 屏上于是又被
    二次放大。改成直接输出物理像素、由 QLabel 用 ``setScaledContents`` 缩放，
    无论屏幕是 100% 还是 150%，源像素都比目标多，缩放方向永远是缩小。

    注意清晰度的物理上限就是原图头像的 60px，所以调用方传 60~64 即可，
    传更大只是把 60px 的图插值放大，不会更清楚。
    """
    import base64

    from PySide6.QtCore import QRectF, Qt
    from PySide6.QtGui import QImage, QPainter, QPainterPath, QPixmap

    try:
        raw = base64.b64decode(CREATOR_BANNER_PNG)
    except Exception:
        return QPixmap()
    src = QImage.fromData(raw)
    if src.isNull():
        return QPixmap()

    x, y, w, h = AVATAR_RECT
    crop = src.copy(x, y, w, h)
    px = max(1, int(pixel_size))
    crop = crop.scaled(
        px, px,
        Qt.AspectRatioMode.IgnoreAspectRatio,
        Qt.TransformationMode.SmoothTransformation,
    )

    canvas = QImage(px, px, QImage.Format.Format_ARGB32_Premultiplied)
    canvas.fill(Qt.GlobalColor.transparent)
    painter = QPainter(canvas)
    painter.setRenderHint(QPainter.RenderHint.Antialiasing, True)
    path = QPainterPath()
    path.addEllipse(QRectF(0, 0, px, px))
    painter.setClipPath(path)
    painter.drawImage(0, 0, crop)
    painter.end()

    return QPixmap.fromImage(canvas)
